/// A props binding that is ever written holds no known value where it is read: the body is unknown for it.
#[test]
fn a_written_props_binding_hands_the_object_on_and_records_nothing_through_it() {
    for body in [
        "props = other; return <Child value={props.value} />",
        "props += x; return <i title={props.t} />",
        "props++; return <i title={props.t} />",
        "for (props of xs) {} return <i title={props.t} />",
        "props = { ...props }; return <i title={props.t} />",
        "({ props } = obj); return <i title={props.t} />",
        "[props] = xs; return <i title={props.t} />",
        "var props = other; return <i title={props.t} />",
        "delete props.a; return <i />",
        "x = props; return <i />",
        "[a] = props; return <i />",
    ] {
        let source = format!("export function C(props: any) {{ let a, x; {body} }}");
        let facts = facts(&source, "C");
        assert!(facts.handed_on, "{body}");
        assert_eq!(reads(&facts), Vec::<&str>::new(), "{body}");
        for element in &facts.elements {
            for attribute in &element.attributes {
                assert!(matches!(attribute, JsxAttributeFact::Named { prop: None, .. }), "{body}");
            }
        }
    }
}

#[test]
fn a_written_rest_binding_is_not_the_props_object() {
    let facts = facts("export function C({ a, ...r }: any) { r = other; return <Child {...r} v={r.v} /> }", "C");
    assert!(facts.handed_on);
    assert!(!facts.elements.iter().flat_map(|e| &e.attributes).any(|attr| matches!(attr, JsxAttributeFact::Spread { of: SpreadOf::Rest })));
}

#[test]
fn a_destructuring_assignment_reads_its_keys_only_when_its_value_is_discarded() {
    let facts = facts("export function C(props: any) { let a; ({ a } = props); return <i /> }", "C");
    assert!(!facts.handed_on);
    assert_eq!(reads(&facts), ["a"]);
    for source in [
        "let a; use(({ a } = props)); return <i />",
        "let a; const q = ({ a } = props); return <i />",
        "let a; return ({ a } = props);",
    ] {
        let facts = facts(&format!("export function C(props: any) {{ {source} }}"), "C");
        assert!(facts.handed_on, "{source}");
    }
}

#[test]
fn a_default_parameter_and_a_declaration_destructuring_are_not_writes() {
    let facts = facts("export function C(props = defaults) { const { a } = props; return <i title={props.b} /> }", "C");
    assert!(!facts.handed_on);
    assert_eq!(reads(&facts), ["a", "b"]);
}
